namespace JingFamily {
 public class ImportBatch {
  public FamilyData Data;
  public Dictionary<string,string> SourceIds=new Dictionary<string,string>();
  public string SourceName;
  public FamilyData Combine(bool append){var d=append?Store.Deserialize(Store.Serialize(Store.Data)):new FamilyData{Title=Data.Title};d.People.AddRange(Data.People);Store.Validate(d);return d;}
  public FamilyData CombineUpdate(){var d=Workshop.Clone();var map=Data.People.ToDictionary(p=>p.Id,p=>SourceIds[p.Id]);foreach(var id in map.Values)if(!d.People.Any(p=>p.Id==id))throw new Exception("编号「"+id+"」不在当前家谱中。更新模式请使用本软件「导出可编辑表格」生成的文件，并保留编号。");var updated=Store.Deserialize(Store.Serialize(Data));foreach(var p in updated.People){string oldId=p.Id;p.Id=map[oldId];var original=d.People.Find(x=>x.Id==p.Id);p.Portrait=original.Portrait;p.FatherId=p.FatherId==""?"":map[p.FatherId];p.MotherId=p.MotherId==""?"":map[p.MotherId];p.Spouses=p.Spouses.Select(x=>map[x]).ToList();}var ids=new HashSet<string>(updated.People.Select(x=>x.Id));foreach(var p in d.People)p.Spouses.RemoveAll(x=>ids.Contains(x));d.People.RemoveAll(p=>ids.Contains(p.Id));d.People.AddRange(updated.People);foreach(var p in updated.People)foreach(var id in p.Spouses){var other=d.People.Find(x=>x.Id==id);if(!other.Spouses.Contains(p.Id))other.Spouses.Add(p.Id);}Store.Validate(d);return d;}
 }
 public static class Templates {
  public static readonly string[] Headers={"编号","姓名","性别","出生日期","去世日期","籍贯","字辈","父亲编号","母亲编号","配偶编号","职业","住址","联系方式","生平"};
